CREATE INDEX IF NOT EXISTS idx_myy_corp_member_dim_latest_kyc_dtm
  ON myy_corp_member_dim (latest_kyc_dtm);

CREATE INDEX IF NOT EXISTS idx_myy_corp_member_dim_onboarding_filter
  ON myy_corp_member_dim (account_status, kyc_status, latest_kyc_dtm);

COMMIT;

SELECT COUNT(*) AS total_rows
FROM myy_corp_member_dim;

SELECT COUNT(DISTINCT cust_id) AS expected_onboarding_count
FROM myy_corp_member_dim
WHERE (
  (account_status = '활성화계정' AND kyc_status = '고객확인완료')
  OR (account_status = '휴면계정' AND kyc_status = '고객확인전단계')
)
AND latest_kyc_dtm >= TIMESTAMP '2025-01-01 00:00:00';

SELECT market_stage, corp_market_type, is_core, COUNT(DISTINCT cust_id) AS expected_count
FROM myy_corp_member_dim
WHERE (
  (account_status = '활성화계정' AND kyc_status = '고객확인완료')
  OR (account_status = '휴면계정' AND kyc_status = '고객확인전단계')
)
AND latest_kyc_dtm >= TIMESTAMP '2025-01-01 00:00:00'
GROUP BY market_stage, corp_market_type, is_core
ORDER BY market_stage, corp_market_type, is_core;
